/** Engine tuning shared by every agent of one language (LLM + TTS model). */
interface LangEngine {
  llm: string;
  /** Omitted when the LLM takes no reasoning_effort (the platform stores null). */
  reasoningEffort?: "none" | "low" | "medium" | "high";
  /** IANA zone for the agent's clock (system__time); omitted = platform default. */
  timezone?: string;
  ttsModel: string;
  similarityBoost: number;
}

const LANG_ENGINE: Record<"en" | "ja", LangEngine> = {
  // Reasoning stays off: voice turns can't afford thinking latency.
  en: {
    llm: "gpt-5.6-luna",
    reasoningEffort: "none",
    ttsModel: "eleven_v3_conversational",
    similarityBoost: 0.8,
  },
  // Tuned by ear on tsubaki-vesper-ja in the dashboard, then rolled out to the
  // whole JA set: a non-reasoning flash LLM and the v4 turbo TTS read.
  ja: {
    llm: "deepseek-v41-flash",
    timezone: "Asia/Singapore",
    ttsModel: "eleven_v4_turbo",
    similarityBoost: 0.75,
  },
};

/** Language-specific half of a persona: voice casting + spoken/prompt text. */

